actions.new:
def queue_sources() -> list[tuple[str, str]]:
    """Return legacy queue files plus isolated per-job producer refs.

    Each producer may publish to worker/job/<job_id>, so it never races the
    Worker's result/health commits on worker/requests or another producer's ref.
    The legacy branch remains readable during migration.
    """
    sources: list[tuple[str, str]] = []

    git("fetch", "--quiet", REMOTE, QUEUE_BRANCH)
    legacy = git(
        "ls-tree", "-r", "--name-only", f"{REMOTE}/{QUEUE_BRANCH}", "worker_queue/inbox"
    )
    sources.extend(
        (QUEUE_BRANCH, line.strip())
        for line in legacy.stdout.splitlines()
        if line.strip().startswith("worker_queue/inbox/")
        and line.strip().endswith(".json")
    )

    refspec = (
        f"+refs/heads/{JOB_BRANCH_PREFIX}*:"
        f"refs/remotes/{REMOTE}/{JOB_BRANCH_PREFIX}*"
    )
    git("fetch", "--quiet", REMOTE, refspec)
    refs = git(
        "for-each-ref",
        "--format=%(refname:short)",
        f"refs/remotes/{REMOTE}/{JOB_BRANCH_PREFIX}",
    )
    remote_prefix = f"{REMOTE}/"
    for remote_ref in refs.stdout.splitlines():
        remote_ref = remote_ref.strip()
        if not remote_ref.startswith(remote_prefix):
            continue
        branch = remote_ref[len(remote_prefix):]
        listing = git(
            "ls-tree", "-r", "--name-only", remote_ref, "worker_queue/inbox"
        )
        for line in listing.stdout.splitlines():
            path = line.strip()
            if path.startswith("worker_queue/inbox/") and path.endswith(".json"):
                sources.append((branch, path))

    return sorted(set(sources))


def read_remote(branch: str, path: str) -> str:
    return git("show", f"{REMOTE}/{branch}:{path}").stdout

